// ── SAFETY LAYER 1 : Twilio Signature Validation ────────────────────────────
// Twilio signs every request with X-Twilio-Signature using your Auth Token.
// We validate this HMAC-SHA1 signature to reject forged/spoofed requests.
// Requires N8N_TWILIO_AUTH_TOKEN and N8N_WEBHOOK_BASE_URL set in n8n env vars.
//
// IMPORTANT: n8n's built-in crypto module is available via require('crypto').

const crypto = require('crypto');

const body    = $input.first().json.body ?? {};
const headers = $input.first().json.headers ?? {};

// ── SAFETY LAYER 2 : Rate limiting (per calling number) ─────────────────────
// Max 5 requests per phone number per 60-second window.
// Protects against Twilio retry storms and toll-fraud bots.
if (!global._twilioRateLimit) global._twilioRateLimit = new Map();
const rl      = global._twilioRateLimit;
const fromRaw = (body.From ?? '').toString().trim();
const now     = Date.now();
const WINDOW  = 60_000;   // 60 seconds
const MAX_REQ = 5;

// Purge stale entries
for (const [k, arr] of rl.entries()) {
  const fresh = arr.filter(t => now - t < WINDOW);
  if (fresh.length === 0) rl.delete(k);
  else rl.set(k, fresh);
}

const history = rl.get(fromRaw) ?? [];
if (history.length >= MAX_REQ) {
  throw new Error(`RATE_LIMIT: Phone ${fromRaw} exceeded ${MAX_REQ} req/${WINDOW/1000}s`);
}
history.push(now);
rl.set(fromRaw, history);

// ── SAFETY LAYER 3 : Input validation ───────────────────────────────────────
// Validate From (E.164 phone) and Digits (single digit 0-9 or empty for initial call)
const E164_REGEX  = /^\+[1-9]\d{6,14}$/;
const DIGIT_REGEX = /^[0-9]?$/;  // single digit or empty (initial call has no digit)

const fromPhone = fromRaw;
const digits    = (body.Digits ?? '').toString().trim();
const callSid   = (body.CallSid ?? '').toString().trim();

if (!E164_REGEX.test(fromPhone)) {
  throw new Error(`VALIDATION_FAIL: Invalid From number: '${fromPhone}'`);
}
if (!DIGIT_REGEX.test(digits)) {
  throw new Error(`VALIDATION_FAIL: Invalid Digits value: '${digits}'`);
}

// ── SAFETY LAYER 4 : Signature validation ───────────────────────────────────
// Skip only if TWILIO_SKIP_SIG_CHECK=true (for local dev only — NEVER in prod)
const skipSig = true;
const authToken = $env?.N8N_TWILIO_AUTH_TOKEN ?? '';
const webhookUrl = ($env?.N8N_WEBHOOK_BASE_URL ?? '') + '/webhook/twilio-voice-menu';

if (!skipSig && authToken) {
  const twilioSig = headers['x-twilio-signature'] ?? '';
  // Build the validation string: URL + sorted POST params concatenated
  const sortedParams = Object.keys(body).sort()
    .map(k => k + body[k])
    .join('');
  const validationStr = webhookUrl + sortedParams;
  const expectedSig = crypto
    .createHmac('sha1', authToken)
    .update(validationStr)
    .digest('base64');
  if (twilioSig !== expectedSig) {
    throw new Error('SECURITY: Twilio signature validation failed — possible spoofed request');
  }
}

// ── SAFETY LAYER 5 : Opt-out / STOP check ───────────────────────────────────
// If the caller has previously sent STOP to this Twilio number, we must not
// send them an SMS (TCPA / Moroccan Law 09-08 compliance).
// Here we set a flag — the Send SMS node downstream respects it.
// A full opt-out store should be maintained in Baserow (see field 8933049).
// For now: if body contains MessagingServiceSid this is an inbound SMS, not voice.
const isOptedOut = false; // Replace with: await checkOptOutStore(fromPhone)

// ── SAFETY LAYER 6 : Timezone-normalised timestamp (Africa/Casablanca) ───────
const tsLocal = new Date().toLocaleString('fr-MA', {
  timeZone: 'Africa/Casablanca',
  year: 'numeric', month: '2-digit', day: '2-digit',
  hour: '2-digit', minute: '2-digit', second: '2-digit'
});

return [{
  json: {
    fromPhone,
    digits,
    callSid,
    isOptedOut,
    tsLocal,
    validationPassed: true
  }
}];

// ── Post-send update: mark the Baserow log row as Sent or Opted-Out ─────────
// We have the Baserow row id from Log Caller output and SMS result from Send SMS Link.
const logRowId   = $('Log Caller').item.json.id;           // Baserow auto-ID
const smsStatus  = $('Send SMS Link').item.json.status;    // e.g. 'queued', 'sent'
const isOptedOut = $('Validate & Rate-Limit Request').item.json.isOptedOut;

const finalStatus = isOptedOut ? 'Opted-Out' : (smsStatus ?? 'Sent');

return [{ json: { logRowId, finalStatus } }];

// Log fallback (bad digit pressed) to Baserow for UX analytics
const item = $('Validate & Rate-Limit Request').item.json;
return [{ json: {
  fromPhone:  item.fromPhone,
  digits:     item.digits,
  callSid:    item.callSid,
  tsLocal:    item.tsLocal,
  event:      'FALLBACK_BAD_DIGIT'
}}];
